/**
 * The bank. Three calls: money goes out at a merchant, money comes in from a
 * payer, and money moves from an account into a pocket.
 *
 * This is the only part of the money subsystem that is not in `init/`. The
 * records, the balances, the pay calendar, the purpose of each account and how
 * readily each person reaches for cash are all generated by
 * `kierston/init/personal_records/banking.py` and packed into holdings.bin.
 * What lives here is the surface: something that can be called at a simulated
 * minute, decides which account and which card, moves the money, and writes a
 * row saying it did.
 *
 * The API holds no seed. Everything that varies between two otherwise
 * identical transactions is hashed out of the transaction itself, and
 * everything that varies between two people is a record. That is not a
 * stylistic choice — a seeded generator on this object would make every call
 * depend on how many calls preceded it, and replaying a day's transactions in
 * a different order would produce a different day. The one thing that does
 * legitimately depend on order is the balance, which is what a ledger is.
 *
 * MONEY IS DOLLARS, everywhere, in and out — a float carrying cents. Every
 * balance change goes through `settle`, which rounds to the cent, and that is
 * not decoration: a float added to and subtracted from all day accumulates
 * representation error, and a balance that has drifted to $84.11999999999999
 * compares wrongly against the next $84.12 purchase. Rounding at each step
 * keeps the error from compounding past the cent it started in.
 *
 * `_timestamp` is underscored on both calls because it is not a fact about the
 * payment the way the amount and the merchant are — it is the simulated minute
 * the caller is currently at, and it exists so the row lands at the right
 * point in the day rather than at the point the code happened to run.
 */

import {
  cashAccount, depositTarget, loadHoldings, type Account, type Card,
  type Holdings, type Position, type PositionState,
} from "./accounts.ts";

export type { PositionState } from "./accounts.ts";
import { available, cashChance, chooseCard, spendable, transactionRng }
  from "./routing.ts";

export { payerFor, benefitPayer } from "./payers.ts";
export { nextPayday, lastPayday, paydaysBetween, annualNet } from "./payroll.ts";
export { loadHoldings } from "./accounts.ts";
export type { Account, Card, IncomeStream, Position } from "./accounts.ts";

/** Where a merchant is, as ground truth rather than as the payer sees it. */
export interface Location {
  /**
   * A street address, where the caller has one. Optional because the venue
   * catalogue does not: `venues.ts` is built from OSM tags and coordinates,
   * and a fabricated address would be worse than an absent one.
   */
  readonly address?: string;
  readonly lat?: number;
  readonly lon?: number;
  /** The POI or venue id, when the caller has one. */
  readonly id?: string;
}

export interface PaymentRequest {
  readonly person: number;
  /** ISO 18245 merchant category. See util_scripts/assign_mcc.py. */
  readonly mcc: number;
  readonly merchant: string;
  /** Dollars, with cents. */
  readonly amount: number;
  /** The simulated minute this happens at. */
  readonly _timestamp: number;
  readonly location?: Location;
  /** An account number to force. Normally omitted — the bank picks. */
  readonly account?: string;
  /** A card's last four to force. Normally omitted. */
  readonly card?: string;
  /**
   * How this was paid, where the caller already knows.
   *
   * Bills and explicit purchase instructions can choose an instrument. A direct debit set up with the
   * gas company is a direct debit, and routing it through `cashChance` and
   * `chooseCard` would pay the gas bill in twenties one month and on a credit
   * card the next. Everything discretionary leaves this alone and lets the
   * bank decide, which is the normal case and the one `routing.ts` is fitted
   * for.
   */
  readonly instrument?: Instrument;
}

/**
 * Paying down a card, which is not a purchase and does not have a merchant.
 *
 * The gap this closes is visible in any long run: `charge` puts money onto a
 * credit card and nothing ever takes it off, so every revolving balance in the
 * city grows without bound and `available` shrinks to nothing by the second
 * month. A card payment is two movements in one row — an account goes down and
 * the card's drawn balance goes down with it — and it is the only call here
 * that touches two of a person's own instruments at once.
 */
export interface CardPaymentRequest {
  readonly person: number;
  /** The card's last four. Which plastic is being paid off. */
  readonly card: string;
  /** Dollars. The caller clamps this to what is actually owed. */
  readonly amount: number;
  readonly _timestamp: number;
  /** The issuer, as it prints on a statement. */
  readonly merchant: string;
  /** An account to draw from. Normally omitted — the bank picks. */
  readonly account?: string;
}

export interface TransferRequest {
  readonly person: number;
  /** The payer's name. `payerFor` supplies a stand-in when there is none. */
  readonly sender: string;
  /** Dollars, with cents. */
  readonly amount: number;
  readonly _timestamp: number;
  readonly account?: string;
  readonly memo?: string;
  /**
   * Money that arrives as notes rather than into an account.
   *
   * Wages paid in currency, which `banking.py` gives to between 3% and 30% of
   * workers depending on their sector and whether they have a taxpayer id. The
   * flag exists because the cash row is the one account with no number to name
   * — it is a pocket, not an account — so a caller cannot route to it the way
   * it routes to everything else.
   */
  readonly cash?: boolean;
}

export interface WithdrawalRequest {
  readonly person: number;
  /** Dollars. Whole notes — a machine does not dispense cents. */
  readonly amount: number;
  readonly _timestamp: number;
  /** The machine, or the counter. Shown on the statement the way a bank does. */
  readonly merchant: string;
  readonly location?: Location;
  /** An account number to force. Normally omitted — the bank picks. */
  readonly account?: string;
}

export type Instrument = "debit" | "credit" | "cash" | "ach" | "check";

export type DeclineReason =
  | "no_position" | "insufficient_funds" | "no_instrument" | "invalid_amount";

export interface Transaction {
  readonly kind: "payment" | "transfer_in" | "withdrawal" | "card_payment";
  readonly person: number;
  readonly _timestamp: number;
  /** Dollars. Positive on the way in and on the way out — `kind` says which. */
  readonly amount: number;
  readonly approved: boolean;
  readonly decline?: DeclineReason;
  readonly instrument?: Instrument;
  readonly account?: string | null;
  readonly card?: string | null;
  readonly network?: string | null;
  readonly mcc?: number;
  readonly merchant?: string;
  readonly sender?: string;
  readonly memo?: string;
  readonly location?: Location;
  /** The balance of whatever moved, after it moved. Null on a decline. */
  readonly balanceAfter: number | null;
}

/**
 * A balance after a movement, rounded to the cent.
 *
 * Every mutation in this file goes through here rather than assigning the raw
 * sum. Doing the arithmetic in floats is fine; *keeping* the result of it is
 * what drifts, because the error carries into the next subtraction and the one
 * after that.
 */
function settle(balance: number, delta: number): number {
  return Math.round((balance + delta) * 100) / 100;
}

export class Bank {
  private readonly holdings: Holdings;
  readonly ledger: Transaction[] = [];

  constructor(holdings: Holdings) {
    this.holdings = holdings;
  }

  static load(path?: string): Bank {
    return new Bank(loadHoldings(path));
  }

  position(person: number): Position {
    return this.holdings.position(person);
  }

  /** The complete mutable financial state, for a day-boundary checkpoint. */
  state(persons: Iterable<number>): PositionState[] {
    return this.holdings.state(persons);
  }

  /** Apply a previously saved day-boundary checkpoint. */
  restore(state: readonly PositionState[]): void {
    this.holdings.restore(state);
  }

  /**
   * Drop already-exported statement rows without changing financial state.
   *
   * A chronological run keeps this Bank for months. The ledger is evidence
   * written into each day product, not an input to tomorrow's routing, so
   * retaining every old row would turn a small balance checkpoint into an
   * ever-growing event archive in memory.
   */
  clearLedger(): void {
    this.ledger.length = 0;
  }

  /**
   * Spend money at a merchant.
   *
   * With no `account` and no `card` the bank chooses, which is the normal
   * case. The choice runs cash-or-card first, because that decides whether a
   * card is needed at all, then walks the spendable accounts in `spendRank`
   * order until one covers the amount. A credit card is the last resort rather
   * than the first, except where the person's own credit preference and the
   * merchant category both point at one.
   *
   * Declines are real outcomes, not errors. Somebody whose everyday account is
   * overdrawn and who has no card gets a `insufficient_funds` row, and that row
   * is as much a fact about the day as an approval is.
   */
  doPayment(request: PaymentRequest): Transaction {
    const {
      person, mcc, merchant, amount, _timestamp, location, account, card,
    } = request;

    if (!(amount > 0)) {
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: false,
        decline: "invalid_amount", mcc, merchant, location, balanceAfter: null,
      });
    }

    const position = this.holdings.position(person);
    const decline = (reason: DeclineReason) => this.post({
      kind: "payment", person, _timestamp, amount, approved: false,
      decline: reason, mcc, merchant, location, balanceAfter: null,
    });

    if (!position.accounts.length && !position.cards.length) {
      return decline("no_position");
    }

    const rng = transactionRng(person, _timestamp, merchant, amount);

    // A stated instrument is an instruction too, and it short-circuits both
    // the cash draw and the card choice: money leaves an account directly and
    // no plastic is presented. The account is the named one, or the one the
    // person's own deposits land in, which is where a mandate would be set up.
    if (request.instrument === "cash") {
      const cash = cashAccount(position);
      if (!cash) return decline("no_instrument");
      if (cash.balance < amount) return decline("insufficient_funds");
      cash.balance = settle(cash.balance, -amount);
      return this.post({ kind: "payment", person, _timestamp, amount, approved: true,
        instrument: "cash", account: null, card: null, mcc, merchant, location, balanceAfter: cash.balance });
    }
    if (request.instrument === "debit" || request.instrument === "credit") {
      const candidates = position.cards.filter((c) => c.kind === request.instrument
        && (!card || c.lastFour === card));
      const chosen = candidates.find((c) => c.kind === "credit" ? available(c) >= amount
        : position.accounts.some((account) => account.number === c.account && account.balance >= amount)) ?? candidates[0];
      if (!chosen) return decline("no_instrument");
      return this.charge(position, chosen, request);
    }
    if (request.instrument === "ach" || request.instrument === "check") {
      const banked = account
        ? position.accounts.find((a) => a.number === account && a.spendable)
        : spendable(position).find((a) => a.type !== "cash")
          ?? depositTarget(position);
      // A money order, which is what somebody with no account pays the rent
      // with. Declining them instead would say that the 10% of Kierston that
      // does not bank also does not have a landlord, and it was worth about a
      // fifth of every rent payment in the city before this branch existed.
      const source = banked && banked.type !== "cash" ? banked : cashAccount(position);
      if (!source) return decline("no_instrument");
      if (source.balance < amount) return decline("insufficient_funds");
      source.balance = settle(source.balance, -amount);
      const paid = source.type === "cash" ? "cash" : request.instrument;
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: true,
        instrument: paid, account: source.number, card: null,
        mcc, merchant, location, balanceAfter: source.balance,
      });
    }

    // A named card is an instruction and is followed, including into a
    // decline: the caller has said which plastic came out of the wallet.
    if (card) {
      const chosen = position.cards.find((c) => c.lastFour === card);
      if (!chosen) return decline("no_instrument");
      return this.charge(position, chosen, request);
    }

    // Cash first, because it decides whether a card is involved at all.
    const cash = cashAccount(position);
    if (!account && cash && cash.balance >= amount
        && rng.bool(cashChance(position, mcc, amount))) {
      cash.balance = settle(cash.balance, -amount);
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: true,
        instrument: "cash", account: null, card: null, mcc, merchant,
        location, balanceAfter: cash.balance,
      });
    }

    const accounts = account
      ? position.accounts.filter((a) => a.number === account && a.spendable)
      : spendable(position);
    if (account && !accounts.length) return decline("no_instrument");

    for (const candidate of accounts) {
      if (candidate.balance < amount) continue;
      if (candidate.type === "cash") {
        candidate.balance = settle(candidate.balance, -amount);
        return this.post({
          kind: "payment", person, _timestamp, amount, approved: true,
          instrument: "cash", account: null, card: null, mcc, merchant,
          location, balanceAfter: candidate.balance,
        });
      }
      const plastic = chooseCard(position, candidate, mcc, amount, rng);
      if (plastic && plastic.kind === "credit") {
        return this.charge(position, plastic, request);
      }
      candidate.balance = settle(candidate.balance, -amount);
      // An account with no card attached can still be spent from — a transfer
      // or a cheque moves money without plastic — so this is a debit either
      // way, and only the card fields differ.
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: true,
        instrument: plastic ? "debit" : "ach", account: candidate.number,
        card: plastic?.lastFour ?? null, network: plastic?.network ?? null,
        mcc, merchant, location, balanceAfter: candidate.balance,
      });
    }

    // Nothing on deposit covers it. Credit is what is left.
    const credit = position.cards
      .filter((c) => c.kind === "credit" && available(c) >= amount)
      .sort((a, b) => available(b) - available(a))[0];
    if (credit) return this.charge(position, credit, request);

    return decline("insufficient_funds");
  }

  /**
   * Money arriving from outside the city's residents — wages, a benefit, a
   * refund, anything with a payer that is not another person here.
   *
   * It lands in the account set up to receive deposits, which is the salary
   * account where one exists and the everyday account otherwise. Somebody with
   * no bank account at all is credited in cash, because that is what actually
   * happens to them: the money arrives as notes or on a card, and either way
   * it is not sitting in a bank.
   */
  doTransferIn(request: TransferRequest): Transaction {
    const { person, sender, amount, _timestamp, account, memo } = request;

    if (!(amount > 0)) {
      return this.post({
        kind: "transfer_in", person, _timestamp, amount, approved: false,
        decline: "invalid_amount", sender, memo, balanceAfter: null,
      });
    }

    const position = this.holdings.position(person);
    const target = request.cash
      ? cashAccount(position)
      : account
        ? position.accounts.find((a) => a.number === account)
        : depositTarget(position);

    if (!target) {
      return this.post({
        kind: "transfer_in", person, _timestamp, amount, approved: false,
        decline: "no_position", sender, memo, balanceAfter: null,
      });
    }

    target.balance = settle(target.balance, amount);
    return this.post({
      kind: "transfer_in", person, _timestamp, amount, approved: true,
      instrument: target.type === "cash" ? "cash" : "ach",
      account: target.number, sender, memo, balanceAfter: target.balance,
    });
  }

  /**
   * Take notes out of an account, at a machine or over a counter.
   *
   * The third call, and it exists because of what the other two do not do.
   * Wages arrive by `doTransferIn` and land in an account; every cash purchase
   * runs the cash row down and nothing ever runs it back up. Simulate a month
   * without this and every pocket in Kierston is empty, the cash share of
   * payments collapses to nothing, and the `cashChance` table in routing.ts is
   * measuring a city that cannot pay in cash rather than one that chooses not
   * to.
   *
   * Not a payment: no merchant category is charged, no card is presented, and
   * the money does not leave the person — it changes which of their own two
   * places it is sitting in. It declines when the account cannot cover it,
   * which is a real outcome for the same reason a declined card is.
   *
   * `balanceAfter` is the *account's*, not the pocket's, because that is the
   * side of the movement a statement shows.
   */
  doWithdrawal(request: WithdrawalRequest): Transaction {
    const { person, amount, _timestamp, merchant, location, account } = request;

    const decline = (reason: DeclineReason) => this.post({
      kind: "withdrawal", person, _timestamp, amount, approved: false,
      decline: reason, merchant, location, balanceAfter: null,
    });

    if (!(amount > 0)) return decline("invalid_amount");

    const position = this.holdings.position(person);
    const cash = cashAccount(position);
    if (!cash) return decline("no_position");

    const source = account
      ? position.accounts.find((a) => a.number === account && a.spendable)
      : spendable(position).find((a) => a.type !== "cash" && a.debitable);
    if (!source) return decline("no_instrument");
    if (source.balance < amount) return decline("insufficient_funds");

    source.balance = settle(source.balance, -amount);
    cash.balance = settle(cash.balance, amount);
    return this.post({
      kind: "withdrawal", person, _timestamp, amount, approved: true,
      instrument: "cash", account: source.number, merchant, location,
      balanceAfter: source.balance,
    });
  }

  /**
   * Pay down a credit card from a deposit account.
   *
   * Declines the way the other calls do and for the same reason: somebody who
   * cannot cover the minimum this month does not pay it, and the balance they
   * did not clear is still there next month with interest on it. That row is a
   * fact about them, not an error.
   */
  doCardPayment(request: CardPaymentRequest): Transaction {
    const { person, card, amount, _timestamp, merchant, account } = request;

    const decline = (reason: DeclineReason) => this.post({
      kind: "card_payment", person, _timestamp, amount, approved: false,
      decline: reason, merchant, card, balanceAfter: null,
    });

    if (!(amount > 0)) return decline("invalid_amount");

    const position = this.holdings.position(person);
    const plastic = position.cards.find(
      (c) => c.kind === "credit" && c.lastFour === card);
    if (!plastic) return decline("no_instrument");

    const source = account
      ? position.accounts.find((a) => a.number === account && a.spendable)
      : spendable(position).find((a) => a.type !== "cash");
    if (!source) return decline("no_position");
    if (source.balance < amount) return decline("insufficient_funds");

    source.balance = settle(source.balance, -amount);
    // Never below zero: paying more than is drawn would leave a credit balance
    // on the card, which the caller is supposed to have clamped away and which
    // `available` has no meaning for.
    plastic.balance = Math.max(0, settle(plastic.balance, -amount));
    return this.post({
      kind: "card_payment", person, _timestamp, amount, approved: true,
      instrument: "ach", account: source.number, card: plastic.lastFour,
      network: plastic.network, merchant,
      // The account's, like a withdrawal's — that is the side a statement
      // shows the movement on.
      balanceAfter: source.balance,
    });
  }

  /** Charge a card, debit or credit, and write the row. */
  private charge(
    position: Position, card: Card, request: PaymentRequest,
  ): Transaction {
    const { person, mcc, merchant, amount, _timestamp, location } = request;

    if (card.kind === "credit") {
      if (available(card) < amount) {
        return this.post({
          kind: "payment", person, _timestamp, amount, approved: false,
          decline: "insufficient_funds", mcc, merchant, location,
          card: card.lastFour, network: card.network, balanceAfter: null,
        });
      }
      card.balance = settle(card.balance, amount);
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: true,
        instrument: "credit", account: null, card: card.lastFour,
        network: card.network, mcc, merchant, location,
        balanceAfter: card.balance,
      });
    }

    const account = position.accounts.find((a) => a.number === card.account);
    if (!account || !account.spendable || account.balance < amount) {
      return this.post({
        kind: "payment", person, _timestamp, amount, approved: false,
        decline: "insufficient_funds", mcc, merchant, location,
        account: card.account, card: card.lastFour, network: card.network,
        balanceAfter: null,
      });
    }
    account.balance = settle(account.balance, -amount);
    return this.post({
      kind: "payment", person, _timestamp, amount, approved: true,
      instrument: "debit", account: account.number, card: card.lastFour,
      network: card.network, mcc, merchant, location,
      balanceAfter: account.balance,
    });
  }

  private post(transaction: Transaction): Transaction {
    this.ledger.push(transaction);
    return transaction;
  }
}
